class AndroidUe(LteUe):
    """Android Ue"""

    # pylint: disable=too-many-instance-attributes, broad-except, unnecessary-pass
    def __init__(self, name, serial_number, configuration, pyro_client, reservation_validator=lambda: True):
        """

        :param name:
        :param serial_number:
        :param configuration:
        :param pyro_client:
        :param reservation_validator:
        """
        super(AndroidUe, self).__init__(name, configuration)
        self.prepared = False
        self.package_name = None
        self._add_methods_from_ue_control()
        self.reservation_verifying = False
        self.reservation_validator = reservation_validator
        config_reader = self._new_config_reader(configuration)
        self.config_reader = config_reader
        self.voice_call_technology_or_none = config_reader.read_voice_call_technology()
        self.voice_call_technology_timeout = config_reader.read_voice_call_technology_timeout()
        self.voice_call_dialing_timeout = config_reader.read_voice_call_dialing_timeout()
        self.qcat_exe_path = config_reader.read_qcat_exe_path()
        self.qcat_analyzer = config_reader.read_qcat_analyzer()
        self.diag_cfg_path = config_reader.read_diag_cfg_path()
        self.is_qualcomm_prototype = config_reader.read_qualcomm_prototype()
        self.is_ue_rooted = config_reader.read_is_rooted()
        self._phone_number = config_reader.read_phone_number()
        self.network_mode_switch_method = self.config_reader.read_network_mode_switch_method()
        self.attach_service_call_number = self.config_reader.read_attach_service_call_number()
        self.detach_service_call_number = self.config_reader.read_detach_service_call_number()
        self.airplane_mode_switcher_text = self.config_reader.read_airplane_mode_switcher_text()
        self.airplane_mode_switcher_text_attach = self.config_reader.read_airplane_mode_switcher_text_attach()
        self.airplane_mode_switcher_text_detach = self.config_reader.read_airplane_mode_switcher_text_detach()
        self.airplane_mode_confirm_button_text = self.config_reader.read_airplane_mode_confirm_button_text()
        self.mobile_network_text = self.config_reader.read_mobile_network_text()
        self.setting_network_mode_text = self.config_reader.read_setting_network_mode_text()
        self.secret_code = self.config_reader.read_secret_code()
        self.ue_model = None
        self._auto_updater = None
        if serial_number is None:
            self.serial_number = "no S/N"
            self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger,
                                                                 {'area': 'UE', 'ue_id': self.serial_number})
        else:
            self.serial_number = serial_number
            self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(self.logger,
                                                                 {'area': 'UE', 'ue_id': self.serial_number})
            self.pyro_client = pyro_client
            self._auto_updater = AutoUpdater(self.pyro_client.ssh_manager, self.config_reader, serial_number, self.pyro_client.ue_pc_os,
                                             self.config_reader.read_uepc_ip(), self.pyro_client)
        self.ne_id = UeIdentification(identifiers=[('android', self.serial_number)], network_elem_type='UE',
                                      specific_for_tool='android')

    def _new_config_reader(self, configuration):
        return AndroidUeYamlConfigurationReader(configuration)

    def _get_json_string_with_imei_imsi(self):
        imsi = self.config_reader.read_imsi()
        imei = self.config_reader.read_imei()
        values = {}
        if imsi:
            values["imsi"] = imsi
        if imei:
            values["imei"] = imei
        values["serial"] = self.serial_number
        import json
        return json.dumps(values)

    def _set_imei_imsi_on_ue(self):
        json = self._get_json_string_with_imei_imsi()
        self._method_proxy('_set_imei_imsi_on_ue', json)

    @property
    def id(self):
        """
        Return ue id specific for used ue-implementation/tool.

        :return: tool specific ue id
        """
        return self.serial_number

    @property
    def phone_number(self):
        """
        Gets phone number assigned in yaml config file in field phone_number.
        :return: None
        :raises NoDefinedPhoneNumberException if field phone_number is not defined in yaml config file for this UE
        """
        if self._phone_number is None:
            if self.prepared:
                try:
                    self._phone_number = self._method_proxy("get_phone_number")
                    return self._phone_number
                except Exception as e:
                    self.logger.debug(str(e))
                    self.logger.info('Phone number is not available on the SIM card. Using IMSI instead.'
                                     'You can also set it via the phone_number parameter in your config file.')
                    self._phone_number = "+{}".format(self.get_info('IMSI'))
        self.logger.info('Phone number of UE {} is {}'.format(self.serial_number, self._phone_number))
        return self._phone_number

    @phone_number.setter
    def phone_number(self, number):
        """Sets phone number"""
        self._phone_number = number

    def connect_additional_pdn(self, pdn):
        """Attempts to insert new apn entry to UE"""
        if self._method_proxy('is_naa_device_owner') == 'false':
            result = self._method_proxy('set_device_owner')
            if 'ERROR' in result:
                raise DeviceOwnerException(result)
        try:
            pdn_from_config = self.config_reader.get_pdn(pdn)
            json_string = self._convert_yaml_pdn_to_json_string(pdn_from_config)
            result = self._method_proxy('add_new_apn_entry', json_string)
            if 'ERROR' in result:
                raise ApnException(result)
        except KeyError:
            raise Exception('PDN {} not found in configuration'.format(pdn))

    def _convert_yaml_pdn_to_json_string(self, pdn):
        import json
        return json.dumps(pdn)

    def disconnect_additional_pdn(self, pdn):
        """Attempts to remove apn entry, entry_name needs to be same as entryName defined in yaml config file"""
        if self._method_proxy('is_naa_device_owner') == 'false':
            result = self._method_proxy('set_device_owner')
            if 'ERROR' in result:
                raise DeviceOwnerException(result)
        try:
            pdn_from_config = self.config_reader.get_pdn(pdn)
            apn_name = pdn_from_config['entryName']
            result = self._method_proxy('remove_apn_entry', apn_name)
            if ('ERROR' in result):
                raise ApnException(result)
        except KeyError:
            raise Exception('PDN {} not found in configuration'.format(pdn))

    def turn_mobile_data_on(self):
        """Turns mobile data on."""
        success = self._method_proxy('set_mobile_data', state='1')
        if not success:
            raise MobileDataSettingsException('Tried to turn on mobile data on UE, but it didn\'t work!')

    def turn_mobile_data_off(self):
        """Turns mobile data off"""
        success = self._method_proxy('set_mobile_data', state='0')
        if not success:
            raise MobileDataSettingsException('Tried to turn off mobile data on UE, but it didn\'t work!')

    def _verify_ue_manager_mobile_version(self):
        version = self.get_mobile_app_version()
        if version < CURRENT_UE_MANAGER_APP_VERSION_NUMBER:
            self.logger.warning('You are not using newest mobile app version! Some functionalities might not work. Visit '
                                'https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/ '
                                'and download newest version. Your version: {}, latest version: {}.'
                                .format(version, CURRENT_UE_MANAGER_APP_VERSION_NUMBER))

    def _verify_naa_mobile_version(self):
        version = self.get_mobile_app_version()
        if version < CURRENT_NAA_APP_VERSION_NUMBER:
            self.logger.warning('You are not using newest mobile app version! Some functionalities might not work. Visit '
                                'https://artifactory-espoo1.ext.net.nokia.com/artifactory/mn-android-apk/ '
                                'and download newest version. Your version: {}, latest version: {}.'.format(version, CURRENT_NAA_APP_VERSION_NUMBER))

    def check_voicemail_notification(self, expected_result=-1):
        """
        Checks how many voicemail notifications there is on UE. If expected result is not provided, we assume that any amount of voicemail is
        an acceptable result.
        Only runnable on devices with Android 4.4 or higher.
        :param expected_result: Expected number of notifications
        :raises: :py:class:`UeProcedureError`: if expected result differs from actual
        :return:
        """
        os_ver = int(self.get_info('UE_OS_VER'))
        if os_ver < 19:
            raise UeProcedureError('Minimum version of Android for this keyword to work is 4.4!')

        expected_result = int(expected_result)
        result = self._method_proxy('check_voicemail_notification')

        if expected_result == int(result) or (expected_result == -1 and int(result) > 0):
            return True
        raise UeProcedureError('Expected voicemail notification count to contain {} message(s), actual number is {}'.format(expected_result,
                                                                                                                            result))

    def clear_voicemail_notification(self):
        """
        Clears notification about voicemail. Check voicemail notificaiton will return 0 unless new voicemail appears. Also cleans on-screen
        voicemail notifications.
        :return:
        """
        return self._method_proxy('clear_voicemail_notification')

    def send_ussd_message(self, ussd_request):
        """
        Sends new USSD request form UE to network
        Only runnable on devices with Android 8.0 or higher.
        :raises: :py:class:`UeProcedureError`: If UE this method is runs on Android lower than 8.0
        :return:
        """
        android_ver = self._method_proxy('get_ue_info', 'ANDROID_VER')
        if android_ver < MIN_VERSION_TO_RUN_USSD_CODES:
            raise UeProcedureError('Send USSD is supported only on Android 8.0 and higher!')
        self.logger.info('Trying to send USSD request: {}'.format(ussd_request))
        return self._method_proxy('send_ussd_message', ussd_request)

    def get_ussd_response(self, ussd_request_response, expected_result):
        """
        Sends new USSD request form UE to network
        Only runnable on devices with Android 8.0 or higher.
        :param ussd_request_response:USSD request code for which we want to retrieve response
        :param expected_result:Response string we expect to get
        :raises: :py:class:`UeProcedureError`: If UE this method is runs on Android lower than 8.0
        :raises: :py:class:`UeProcedureError`: If expected result is different than actual result
        :return: True if result was same as expected result
        """
        android_ver = self._method_proxy('get_ue_info', 'ANDROID_VER')
        if android_ver < MIN_VERSION_TO_RUN_USSD_CODES:
            raise UeProcedureError('Get USSD is supported only on Android 8.0 and higher!')
        self.logger.info('Trying to retrieve response for {} USSD request'.format('last' if ussd_request_response is None else
                                                                                  ussd_request_response))
        result = self._method_proxy('get_ussd_response', ussd_request_response)
        self.logger.info('Response for {} USSD request is {}'.format(ussd_request_response, result))

        expected_result_for_compare = self._prepare_string_for_compare(expected_result)
        actual_result_for_compare = self._prepare_string_for_compare(result)

        self.logger.info('expected result post string parsing:{}\nactual result post string parsing:{}\nexpected result:{}\nactual result:{}'.
                         format(expected_result_for_compare, actual_result_for_compare, expected_result, result))
        if expected_result_for_compare == actual_result_for_compare:
            return True
        raise UeProcedureError('For ussd code {} expected result was "{}" but actual is "{}"'.format(ussd_request_response, expected_result,
                                                                                                     result))

    def start_audio_playback(self, audio_file_path, alsa_mixer_command='alsa_amixer cset name=\'Incall_Music Audio Mixer MultiMedia1\' \'1\''):
        """
        Executes commands required to inject voice into voice call and starts playback of specified audio file on UE
        :param audio_file_path: absolute path to audio file on UE
        :param alsa_mixer_command: Cmd to run alsa amixer. Because some UEs might have different commands, user can specify command run to fit
        her/his needs
        :return:
        """
        self.logger.debug('voice injection started')
        self._method_proxy('start_audio_playback', audio_file_path, alsa_mixer_command)
        result = self._method_proxy('get_start_audio_playback_result')
        if 'Successfully started playing file' not in result:
            raise UeProcedureError('Error when trying to inject voice into voice call:{}'.format(result))

    def stop_audio_playback(self):
        """
        Stops previously started audio playback on UE
        This won't stop audio playback from apps other than UeManager!
        :return:
        """
        self._method_proxy('stop_audio_playback')

    def get_active_network_technology(self):
        """
        Gets current network technology name: ['-', '?', '2G', '3G', '4G', 'WIFI']
        Where '-' means disconnected.
        Where '?' means unknown.
        :return: Current network technology name.
        """
        return self._method_proxy("get_active_network_technology")

    def prepare_ue(self):
        """Call this after constructor. This method may take some time."""
        if self._auto_updater:
            pass
        self.logger.debug("prepare_ue before reserve")
        self._method_proxy('reserve_ue')
        self.logger.debug("prepare_ue after reserve")
        self.ue_model = self.get_info('DEVICE_MODEL')  # ensure UE has connected and is working
        self.logger.debug("prepare_ue after get model")
        self.check_if_prototype()
        self.logger.debug("Setting rooted state, is_rooted parameter value: {}".format(self.is_ue_rooted))
        self.set_is_rooted()
        self.logger.debug("prepare_ue after check_if_prototype")
        self.package_name = self._method_proxy('get_mobile_app_package_name')
        if self.package_name == UEM_PACKAGE_NAME:
            self.logger.debug("Verify UEM version.")
            self._verify_ue_manager_mobile_version()
        else:
            self.logger.debug("Verify NAA version.")
            self._verify_naa_mobile_version()
        # self._configure_logging_on_ue()  # TODO https://jiradc.ext.net.nokia.com/browse/TAUE-1411
        self._set_imei_imsi_on_ue()
        self.prepared = True

    def _configure_logging_on_ue(self):
        if self.config_reader.read_logging_setting_on_app():
            self._method_proxy("switch_ue_logging", True)
            return
        self._method_proxy("switch_ue_logging", False)

    def check_if_prototype(self):
        """Set is_qualcomm_prototype parameter on AndroidControl object via RPC"""
        if str(self.is_qualcomm_prototype).lower() in ["yes", "true"]:
            self._method_proxy('set_is_qualcomm')
        else:
            self._method_proxy('am_i_qualcomm_prototype')

    def set_is_rooted(self):
        """Set rooted parameter according to the config file"""
        if self.is_ue_rooted:
            if str(self.is_ue_rooted).lower() in ["yes", "true"]:
                self._method_proxy('set_is_rooted')

    def start_reservation_veryfying(self):
        """After this call, this android UE verifies if it's have uptodate reservation on UE PC."""
        self.reservation_verifying = True

    def stop_rrc_logs(self, qcat_analyzer=None, timeout=180, transfer_log_files_from_uepc=True,
                      logs_download_directory=get_robot_variable("OUTPUT_DIR"), filter_file_path=None, mdm=None,
                      return_rrc_log=False, use_decoding=True):
        """Stop diag_mdlog application on Android UE, convert qmdl to .txt and return path to txt file on UE PC"""
        if not self.path_to_qcat_execution_file_exists():
            return None
        qcat_analyzer = self.set_qcat_analyzer(qcat_analyzer)
        filter_file_path_on_uepc = self.prepare_rrc_filter_file_path_on_uepc(filter_file_path)
        is_decoding_required = self._use_decoding_normalize(use_decoding)
        self._oneway_method_proxy('stop_rrc', qcat_analyzer=qcat_analyzer, rrc_filter_file_path=filter_file_path_on_uepc,
                                  mdm=mdm, use_decoding=is_decoding_required)
        downloaded_files_paths = self.wait_for_stop_rrc_and_download_rrc_files(is_decoding_required, timeout,
                                                                               transfer_log_files_from_uepc,
                                                                               logs_download_directory)
        self.actions_for_return_rrc_log(return_rrc_log, downloaded_files_paths)
        self._method_proxy('clean_up_after_rrc_logs')

    def wait_for_stop_rrc_and_download_rrc_files(self, is_decoding_required, timeout, transfer_log_files_from_uepc,
                                                 logs_download_directory):
        downloaded_files_paths = None
        if is_decoding_required:
            self._wait_for_stop_rrc_result(timeout)
            if transfer_log_files_from_uepc:
                downloaded_files_paths = self.get_decoded_rrc_files_from_uepc_to_robot_vm(transfer_log_files_from_uepc,
                                                                                          logs_download_directory)
        else:
            self._wait_for_stop_rrc_result_without_decoding(timeout)
            if transfer_log_files_from_uepc:
                downloaded_files_paths = self.get_raw_qmdl_rrc_file_from_uepc_to_robot_vm(transfer_log_files_from_uepc,
                                                                                          logs_download_directory)
        return downloaded_files_paths

    def get_decoded_rrc_files_from_uepc_to_robot_vm(self, transfer_log_files_from_uepc, logs_download_directory):
        log_files_paths = []
        txt_qmdl_file_path = self.get_path_to_decoded_qmdl_file()
        qmdl_file_path = txt_qmdl_file_path.replace('.txt', '.qmdl')
        self.get_path_to_txt_files_created_from_qmdl()
        log_files_paths.append(txt_qmdl_file_path)
        log_files_paths.append(qmdl_file_path)
        _, downloaded_files_paths = self.download_files_from_uepc(transfer_log_files_from_uepc,
                                                                  log_files_paths,
                                                                  logs_download_directory)
        return downloaded_files_paths

    def get_raw_qmdl_rrc_file_from_uepc_to_robot_vm(self, transfer_log_files_from_uepc, logs_download_directory):
        log_files_paths = []
        qmdl_file_path = self.get_path_to_qmdl_file()
        log_files_paths.append(qmdl_file_path)
        _, downloaded_files_paths = self.download_files_from_uepc(transfer_log_files_from_uepc,
                                                                  log_files_paths,
                                                                  logs_download_directory)
        return downloaded_files_paths

    def get_path_to_decoded_qmdl_file(self):
        output_path = self._method_proxy("get_path_to_decoded_qmdl_file")
        if output_path == 'ERROR':
            ute_logger = getLogger('ute_ue')
            ute_logger.warning('Couldn\'t get parsed .qmdl file from UEPC! Logs won\'t be transferred!')
        return output_path

    def get_path_to_qmdl_file(self):
        output_path = self._method_proxy("get_path_to_decoded_qmdl_file")
        if output_path == 'ERROR':
            ute_logger = getLogger('ute_ue')
            ute_logger.warning('Couldn\'t get raw .qmdl file from UEPC! Logs won\'t be transferred!')
        return output_path

    def get_path_to_txt_files_created_from_qmdl(self):
        output_path = self._method_proxy("get_path_to_txt_files_created_from_qmdl")
        if output_path == 'ERROR':
            self.logger.error('ERROR when trying to get path to txt files created from qmdl, please check logs.')
        return output_path

    def prepare_rrc_filter_file_path_on_uepc(self, filter_file_path):
        filter_file_path_on_uepc = None
        if filter_file_path is not None:
            filter_file_name = filter_file_path.split(sep)[-1]
            filter_file_path_on_uepc = '{}/{}'.format(self.config_reader.read_server_dir(), filter_file_name)
            self.pyro_client.push_file_to_uepc(filter_file_path, filter_file_path_on_uepc)
        return filter_file_path_on_uepc

    def path_to_qcat_execution_file_exists(self):
        if self.qcat_exe_path is None:
            self.logger.error(
                'qcat_exe_path and diag_cfg_path yaml parameters not found! Stop RRC logs keyword will not work!')
            return False
        return True

    def set_qcat_analyzer(self, qcat_analyzer):
        return qcat_analyzer if qcat_analyzer else self.qcat_analyzer

    def download_files_from_uepc(self, transfer_log_files_from_uepc, log_files_paths, logs_download_directory):
        if transfer_log_files_from_uepc:
            return self._get_qmdl_logs_from_uepc(log_files_paths, logs_download_directory)

    def actions_for_return_rrc_log(self, return_rrc_log, downloaded_files_paths):
        data = self._read_qmdl_log(downloaded_files_paths)
        self._provide_data_from_stop_rrc_to_ta_messaging(data)
        if return_rrc_log:
            self.logger.warning("Returning RRC logs from stop rrc keyword may cause Your log.html file to become"
                                " unreadable. You have been warned.")
            all_data_combined = []
            for log in data:
                all_data_combined.extend(log)
            return all_data_combined

    @staticmethod
    def _use_decoding_normalize(use_decoding):
        return False if str(use_decoding).lower() == 'false' else True

    def _is_it_required_to_download_logs(self, transfer_log_files_from_uepc):
        return utils.Utils.parameter_value_to_bool(param_name="transfer_log_files_from_uepc",
                                                   param_value=transfer_log_files_from_uepc,
                                                   value_to_bool_dict={"yes": True, "no": False, "true": True,
                                                                       "false": False,  # pylint: disable=duplicate-key
                                                                       u"yes": True, u"no": False, u"true": True,
                                                                       # pylint: disable=duplicate-key
                                                                       u"false": False})

    def _get_qmdl_logs_from_uepc(self, log_files_paths, download_dir_path=get_robot_variable("OUTPUT_DIR")):
        log_files_paths = [path for path in log_files_paths if path]
        downloaded_logs, paths_to_log_files_on_vm = self._download_log_files(log_files_paths, download_dir_path)
        self.logger.debug('downloaded_logs={} and paths_to_logs_files_on_vm={}'.format(downloaded_logs, paths_to_log_files_on_vm))
        if len(downloaded_logs) != len(log_files_paths):
            not_downloaded_files = set(log_files_paths).difference(set(downloaded_logs))
            ute_logger = getLogger('ute_ue')
            ute_logger.warning('Not all log files have been downloaded! Log files missing: {}'.format(not_downloaded_files))
        return downloaded_logs, paths_to_log_files_on_vm

    def _download_log_files(self, log_files_paths, download_dir_path):
        need_to_encode_string_as_unicode = sys.version_info[0] < 3
        downloaded_logs = []
        file_paths_to_logs_on_vm = []
        for log_file_path in log_files_paths:
            if need_to_encode_string_as_unicode:
                log_file_path = log_file_path.encode('utf-8')
            log_file_name = log_file_path.split('\\')[-1]  # RRC only works on Windows, thus '\\'
            download_full_path = '{}/{}'.format(download_dir_path, log_file_name)
            if self.pyro_client.get_file_from_uepc(log_file_path, download_full_path):
                downloaded_logs.append(log_file_path)
                file_paths_to_logs_on_vm.append(download_full_path)
        return downloaded_logs, file_paths_to_logs_on_vm

    @staticmethod
    def _is_ta_messaging_installed():
        import sys
        if sys.version_info[0] < 3:
            import pkgutil
            messaging_loader = pkgutil.find_loader('ta_messaging')
        else:
            import importlib
            messaging_loader = importlib.find_loader('ta_messaging')
        return messaging_loader is not None

    def _provide_data_from_stop_rrc_to_ta_messaging(self, data):
        try:
            from ta_messaging.message_sources.message_sources_file_based import AndroidFileMessageSource
            if AndroidFileMessageSource.ANDROID_QUEUE in aliases_registry():
                if not data:
                    self.logger.info("Couldn't get decoded qmdl file from VM")
                    return
                for log_file_contents in data:
                    aliases_registry()[AndroidFileMessageSource.ANDROID_QUEUE].put(log_file_contents)
        except ImportError:
            self.logger.info(
                "stop rrc - ta_messaging is not installed, can not provide data from stop rrc to ta_messaging")

    def _read_qmdl_log(self, logs_files_paths):
        idx = 0
        data = []
        self.logger.debug("_read_qmdl_log received these:{} logpaths".format(logs_files_paths))
        while idx < len(logs_files_paths):
            self.logger.debug('logs_file_path[{}] = {}'.format(idx, logs_files_paths[idx]))
            if logs_files_paths[idx].endswith('.txt'):
                with open(logs_files_paths[idx]) as f:
                    self.logger.debug("Returning decoded qmdl file {}".format(f.name))
                    data.append(f.readlines())  # readlines returns a list of lines.
            idx += 1
        if not data:
            self.logger.debug("Didn't find any decoded qmdl files.")
        return data

    def _wait_for_stop_rrc_result(self, timeout):
        end_time = time.time() + float(timeout)
        data = self._method_proxy('is_rrc_result_ready')
        while not data:
            if time.time() > end_time:
                raise UeProcedureError('While waiting for UEPC to decode .qmdl file a timeout has occured. Please check'
                                       ' whether:\n'
                                       '1) You are able to run QCAT manually\n'
                                       '2) You have a valid QCAT license\n'
                                       '3) If You are using license keeper, check if You can run it manually.')
            time.sleep(1)
            data = self._method_proxy('is_rrc_result_ready')
        return True

    def _wait_for_stop_rrc_result_without_decoding(self, timeout):
        end_time = time.time() + float(timeout)
        data = self._method_proxy('is_rrc_result_ready_without_decoding')
        while not data:
            if time.time() > end_time:
                raise UeProcedureError('While waiting for UEPC to store raw .qmdl file a timeout has occured.')
            time.sleep(1)
            data = self._method_proxy('is_rrc_result_ready_without_decoding')
        return True

    def start_rrc_logs(self, diag_cfg_path=None, qmdl_size=None):
        """
        Start diag_mdlog on Android UE - start collecting qmdl file with rrc messages from qualcomm chipset.
        :param diag_cfg_path: path to DIAG.cfg file on Windows UE PC (required to run diag_mdlog application on Android UE)
        :qmdl_size: maximum qmdl file size in MB, int to specify the qmdl size if needed
        """
        if not diag_cfg_path:
            diag_cfg_path = self.diag_cfg_path
        if self.qcat_exe_path is None:
            self.logger.error(
                'qcat_exe_path and diag_cfg_path yaml parameters not found! Start RRC logs keyword will not work!')
            return None
        return self._method_proxy('start_rrc', self.qcat_exe_path, diag_cfg_path, qmdl_size)

    def change_network_mode(self, network_mode_args, network_mode_switch_method=None,
                            mobile_network_text=None, setting_network_mode_text=None,
                            secret_code=None):
        """
        Changes network mode of UE. Not sure all UEs support this method.
        See:
        https://confluence.int.net.nokia.com/display/LTEVERTA/ta_ue+keywords+behavior+on+Android
        :param network_mode_args: string, see UeManagerProtocol.network_mode_nums2names
        :param network_mode_switch_method:
        :param mobile_network_text:
        :param setting_network_mode_text:
        :param secret_code:
        :return: None
        """
        self._get_network_mode_robot_kwargs(network_mode_switch_method=network_mode_switch_method,
                                            mobile_network_text=mobile_network_text,
                                            setting_network_mode_text=setting_network_mode_text,
                                            secret_code=secret_code)
        if str(self.network_mode_switch_method).lower() == 'keyevents' or str(self.network_mode_switch_method).lower() == 'secretcode':
            network_mode = str(list(network_mode_args)[0])
        else:
            network_mode = network_mode_from_robot_to_android_string(network_mode_args)
        return self._method_proxy('change_network_mode', network_mode,
                                  self.attach_service_call_number, self.detach_service_call_number,
                                  self.airplane_mode_switcher_text, self.airplane_mode_confirm_button_text,
                                  self.network_mode_switch_method, self.mobile_network_text,
                                  self.setting_network_mode_text, self.secret_code)

    def change_and_validate_nr_mode(self, nr_mode, nr_card_name="Test Card", settings_text="Prefer 5G NR Mode"):
        return self._method_proxy("_keyevents_change_and_validate_nr_mode", nr_mode, nr_card_name, settings_text)

