class AndroidUeYamlConfigurationReader(object):
    """AndroidUeYamlConfigurationReader"""

    def __init__(self, configuration):
        """
        Basic initialization.

        :param configuration:
        """
        self.config = configuration

    def get_pdn(self, entry_name):
        """Returns given PDN configuration"""
        return self.config['PDN'][entry_name]

    def read_voice_call_technology_timeout(self):
        """
        Config settings

        :return:
        """
        return float(self.config['voice_call_technology_timeout']) if 'voice_call_technology_timeout' in self.config else 60

    def read_voice_call_dialing_timeout(self):
        """
        Config settings

        :return:
        """
        return float(self.config['voice_call_dialing_timeout']) if 'voice_call_dialing_timeout' in self.config else -1

    def read_voice_call_technology(self):
        """
        Config settings

        :return:
        """
        return self.config['voice_call_technology'] if 'voice_call_technology' in self.config else None

    def read_qcat_exe_path(self):
        """
        Config settings

        :return:
        """
        return self.config['qcat_exe_path'] if 'qcat_exe_path' in self.config else None

    def read_qcat_analyzer(self):
        """
        Config settings

        :return:
        """
        return self.config['qcat_analyzer'] if 'qcat_analyzer' in self.config else None

    def read_diag_cfg_path(self):
        """
        Config settings

        :return:
        """
        return self.config['diag_cfg_path'] if 'diag_cfg_path' in self.config else None

    def read_phone_number(self):
        """
        Config settings

        :return:
        """
        return self.config['phone_number'] if 'phone_number' in self.config else None

    def read_network_mode_switch_method(self):
        """
        Config settings

        :return:
        """
        return self.config['network_mode_switch_method'] if 'network_mode_switch_method' in self.config else None

    def read_ussd_config(self):
        """
        Read path to yml file with USSD codes
        :return:
        """
        return self.config['ussd_codes_config'] if 'ussd_codes_config' in self.config else 'missing ussd_codes_config path in ute_ue yml file'

    def read_qualcomm_prototype(self):
        """
        Read qualcomm_prototype parameter from yml file
        :return: qualcomm_prototype parameter's value if set, else 'no'
        """
        return self.config['qualcomm_prototype'] if 'qualcomm_prototype' in self.config else 'no'

    def read_is_rooted(self):
        """
        Read UE root status from yml file
        :return: is_ue_rooted parameter's value if set, else 'no'
        """
        return self.config['is_rooted'] if 'is_rooted' in self.config else 'unknown'

    def read_server_dir(self):
        """
        Read path to pyro server directory from yml file
        :return:  server_dir parameter's value if set, else empty string
        """
        return self.config['server_dir'] if 'server_dir' in self.config else ''

    def read_update_server_ip(self):
        """
        Read path to scp server for automatic update
        :return:  scp_server_ip parameter's value if set, else None
        """
        UPDATE_SERVER_IP = 'update_server_ip'
        return self.config.get(UPDATE_SERVER_IP)

    def read_update_server_port(self):
        """
        Read path to scp directory containing UeManager mobile apk file and version file
        :return:  scp_directory paramter's value if set, else empty string
        """
        UPDATE_SERVER_PORT = 'update_server_port'
        return self.config[UPDATE_SERVER_PORT] if UPDATE_SERVER_PORT in self.config else ''

    def read_update_server_user(self):
        """
        Read path to scp user for automatic update
        :return:  scp_user parameter's value if set, else empty string
        """
        UPDATE_SERVER_USR = 'update_server_user'
        return self.config.get(UPDATE_SERVER_USR)

    def read_update_user_passwd(self):
        """
        Read password for user connecting to server
        :return:  scp_directory paramter's value if set, else empty string
        """
        UPDATE_SERVER_PASSWORD = 'update_server_password'
        return self.config.get(UPDATE_SERVER_PASSWORD)

    def read_server_update_dir(self):
        """
        Read path to scp directory containing UeManager mobile apk file and version file
        :return:  scp_directory paramter's value if set, else empty string
        """
        UPDATE_SERVER_DIR = 'update_server_dir'
        return self.config[UPDATE_SERVER_DIR] if UPDATE_SERVER_DIR in self.config else ''

    def read_desired_app_version(self):
        """
        Read app version to update to
        :return:  app version to update to if set, else empty string
        """
        UPDATE_VERSION = 'ue_manager_version'
        version = self.config.get(UPDATE_VERSION)
        if version:
            return version
        UPDATE_VERSION = 'update_version'
        return self.config.get(UPDATE_VERSION)

    def read_apk_to_update(self):
        """
        Read which apk to update to. Valid Options are NAA and UeManager
        :return:  scp_directory paramter's value if set, else empty string
        """
        UPDATE_APK = 'update_apk'
        return self.config.get(UPDATE_APK)

    def read_uepc_ip(self):
        """
        Read path to scp directory containing UeManager mobile apk file and version file
        :return:  scp_directory paramter's value if set, else empty string
        """
        UE_PC_IP = 'ue_pc_ip'
        return self.config[UE_PC_IP] if UE_PC_IP in self.config else ''

    def read_turn_artifactory_update_off(self):
        """
        Read path to scp directory containing UeManager mobile apk file and version file
        :return:  scp_directory paramter's value if set, else empty string
        """
        TURN_ARTIFACTORY_UPDATE_OFF = 'turn_artifactory_update_off'
        return True if TURN_ARTIFACTORY_UPDATE_OFF in self.config else False

    def read_artifactory_url(self):
        """
        Read artifactory url
        :return:  artifactory url if set, else empty string
        """
        ARTIFACTORY_URL = 'artifactory_url'
        return self.config.get(ARTIFACTORY_URL)

    def read_artifactory_repository(self):
        """
        Read artifactory repo
        :return:  artifactory repo if set, else empty string
        """
        ARTIFACTORY_REPO = 'artifactory_repo'
        return self.config.get(ARTIFACTORY_REPO)

    def read_ssh_key_file_path(self):
        """
        Read path to file containing ssh key used for authentication
        :return: path to ssh key file
        """
        SSH_KEY_PATH = 'ssh_key_path'
        return self.config.get(SSH_KEY_PATH)

    def read_ssh_key_type(self):
        """
        Read SSH keytype
        :return: SSH key type
        """
        SSH_KEY_TYPE = 'ssh_key_type'
        return self.config.get(SSH_KEY_TYPE)

    def read_airplane_mode_switcher_text(self):
        """
        Reads text from config that is supposed to be next to the switcher toggling airplane mode
        :return: key events custom directions
        """
        AIRPLANE_MODE_SWITCHER_TEXT = 'airplane_mode_switcher_text'
        return self.config.get(AIRPLANE_MODE_SWITCHER_TEXT)

    def read_airplane_mode_switcher_text_attach(self):
        """
        Reads text from config that is supposed to be next to the switcher toggling airplane mode off
        Related to UTETAF-4891
        :return: key events custom directions
        """
        AIRPLANE_MODE_SWITCHER_TEXT_ATTACH = 'airplane_mode_switcher_text_attach'
        return self.config.get(AIRPLANE_MODE_SWITCHER_TEXT_ATTACH)

    def read_airplane_mode_switcher_text_detach(self):
        """
        Reads text from config that is supposed to be next to the switcher toggling airplane mode on
        Related to UTETAF-4891
        :return: key events custom directions
        """
        AIRPLANE_MODE_SWITCHER_TEXT_DETACH = 'airplane_mode_switcher_text_detach'
        return self.config.get(AIRPLANE_MODE_SWITCHER_TEXT_DETACH)

    def read_airplane_mode_confirm_button_text(self):
        """
        Reads text from config that is supposed to be on popup window's button to confirm toggling airplane mode
        :return: key events custom directions
        """
        airplane_mode_confirm_button_text = 'airplane_mode_confirm_button_text'
        return self.config.get(airplane_mode_confirm_button_text)

    def read_mobile_network_text(self):
        """
        Reads text from config that is supposed to be label of Mobile networks in gui
        :return: widget text
        """
        MOBILE_NETWORK_TEXT = 'mobile_network_text'
        return self.config.get(MOBILE_NETWORK_TEXT)

    def read_setting_network_mode_text(self):
        """
        Reads text from config that is supposed to be label of Preferred network mode in gui
        :return: widget text
        """
        SETTING_NETWORK_MODE_TEXT = 'setting_network_mode_text'
        return self.config.get(SETTING_NETWORK_MODE_TEXT)

    def read_secret_code(self):
        """
        Reads secret code text from config
        :return: secret code
        """
        SECRET_CODE = 'secret_code'
        return self.config.get(SECRET_CODE)

    def read_attach_service_call_number(self):
        """
        Reads service call number used to attach UE in several phones.
        Refer to https://confluence.ext.net.nokia.com/display/AbstractLibs/Getting+service+calls+on+Android+UE
        to get service call for Your UE.
        """
        ATTACH_SERVICE_CALL_KEY = 'service_call_attach'
        return self.config.get(ATTACH_SERVICE_CALL_KEY, None)

    def read_detach_service_call_number(self):
        """
        Reads service call number used to detach UE in several phones.
        Refer to https://confluence.ext.net.nokia.com/display/AbstractLibs/Getting+service+calls+on+Android+UE
        to get service call for Your UE.
        Attach/detach can be toggled, or can be an on/off service call. If detach service call is not present in config,
        this method will return attach service call assuming its a toggle service call.
        """
        ATTACH_SERVICE_CALL_KEY = 'service_call_attach'
        DETACH_SERVICE_CALL_KEY = 'service_call_detach'
        if DETACH_SERVICE_CALL_KEY in self.config:
            return self.config.get(DETACH_SERVICE_CALL_KEY)
        if ATTACH_SERVICE_CALL_KEY in self.config:
            return self.config.get(ATTACH_SERVICE_CALL_KEY)
        return None

    def read_logging_setting_on_app(self):
        """
        Read whether to log to file on UE or not
        :return: boolean indicating whether to log or not
        """
        LOG_ON_UE = "enable_ue_logs"
        logging_val = self.config.get(LOG_ON_UE, None)
        if not logging_val:
            return False
        if logging_val.lower() == 'yes' or logging_val.lower() == 'true':
            return True
        return False

    def read_download_debug(self):
        """
        Check if debug versions should be downloaded from update server
        :return: boolean indicating whether debug version should be downloaded or not
        """
        DOWNLOAD_DEBUG = "download_debug"
        download_val = self.config.get(DOWNLOAD_DEBUG, None)
        if not download_val:
            return False
        return download_val.lower() in ['yes', 'true']

    def read_imsi(self):
        """
        If present in config, it will be stored in UE, to be retrieved later. Used in situations where due to
        API restrictions it cannot be obtained directly from UE.
        :return: IMSI number to set on ue or None
        """
        IMSI = 'imsi'
        return self.config.get(IMSI)

    def read_imei(self):
        """
        If present in config, it will be stored in UE, to be retrieved later. Used in situations where due to
        API restrictions it cannot be obtained directly from UE.
        :return: IMSI number to set on ue or None
        """
        IMEI = 'imei'
        return self.config.get(IMEI)
